using CosmicShore.Utility;
using UnityEngine;

namespace CosmicShore.Gameplay
{
    /// <summary>
    /// The timing and brightness of the Charge light (<see cref="CrystalChargeArcs"/>): the seam walk on the Charge crystal
    /// and the chained flux arcs on the omni (Omni Motion Lab rounds 4-5, <c>Docs/Studios/OMNI_MOTION_LAB.md</c>). One
    /// profile for both crystals: one element, one look (<c>Docs/PALETTE.md</c> §2.10).
    ///
    /// <c>CrystalChargeArcsProfile.asset</c> is GENERATED by <c>Tools/Build/author_omni_crystal_triangles.py</c> from the
    /// lab's pick, and its <c>--check</c> fails if the asset drifts. Retune in the lab, then in the generator.
    /// </summary>
    [CreateAssetMenu(fileName = "CrystalChargeArcsProfile", menuName = "ScriptableObjects/Crystals/Charge Arcs Profile")]
    public class CrystalChargeArcsProfileSO : ScriptableObject
    {
        [Header("Overall")]
        [Tooltip("x the speed of every beat (every duration below is divided by this).")]
        [SerializeField, Range(0.25f, 3f)] float rate = 1f;

        [Tooltip("x the bolts' brightness.")]
        [SerializeField, Range(0f, 4f)] float boltIntensity = 1f;

        [Tooltip("x the lit plates' brightness (a petal beside the seam walk, a pentagon charging or taking a discharge).")]
        [SerializeField, Range(0f, 4f)] float glowIntensity = 1f;

        [Header("Seam walk (the Charge crystal)")]
        [Tooltip("Seconds a seam between two blooms takes to strike.")]
        [SerializeField, Range(0.01f, 0.5f)] float seamStrikeSeconds = 0.07f;

        [Tooltip("Seconds the bolt holds on a seam before the next one strikes: the shortest hold.")]
        [SerializeField, Range(0f, 1f)] float seamDwellMinSeconds = 0.1f;

        [Tooltip("The longest hold (each hold is drawn between the two).")]
        [SerializeField, Range(0f, 2f)] float seamDwellMaxSeconds = 0.28f;

        [Tooltip("Seconds a struck seam takes to fade behind the bolt.")]
        [SerializeField, Range(0.05f, 3f)] float seamFadeSeconds = 0.85f;

        [Tooltip("x the light on the petals beside the bolt (on top of glowIntensity). Low, so the plasma reads over the petals it lights.")]
        [SerializeField, Range(0f, 2f)] float seamPetalGlow = 0.35f;

        [Header("Flux arcs (the omni)")]
        [Tooltip("Seconds between one discharge and the next. Each leaps on from the pentagon the last one landed on.")]
        [SerializeField, Range(0.2f, 5f)] float fluxGapSeconds = 0.9f;

        [Tooltip("Seconds the source pentagon charges (lights) before the arc leaps.")]
        [SerializeField, Range(0f, 2f)] float fluxChargeSeconds = 0.45f;

        [Tooltip("Seconds the arc takes to reach the sink.")]
        [SerializeField, Range(0.01f, 0.5f)] float fluxStrikeSeconds = 0.06f;

        [Tooltip("Seconds the arc holds once it has landed.")]
        [SerializeField, Range(0f, 2f)] float fluxHoldSeconds = 0.45f;

        [Tooltip("Seconds the arc and both pentagons take to fade.")]
        [SerializeField, Range(0.05f, 2f)] float fluxFadeSeconds = 0.45f;

        [Tooltip("The fraction of the arc at each end over which its five strands fan smoothly onto the pentagon's five corners; between, they run on as one coaxial bundle (each strand one ribbon the whole way: no seam).")]
        [SerializeField, Range(0.05f, 0.5f)] float fluxFork = 0.3f;

        [Tooltip("The nearest a sink may be to its source, in degrees round the crystal.")]
        [SerializeField, Range(0f, 180f)] float fluxMinDegrees = 55f;

        [Tooltip("The farthest a sink may be from its source, in degrees round the crystal.")]
        [SerializeField, Range(0f, 180f)] float fluxMaxDegrees = 125f;

        [Tooltip("Between the forks the five strands run as one coaxial bundle: how far each runs off the arc's centre line, x the crystal's radius. Small enough to read as one cable, big enough to keep the five filaments apart.")]
        [SerializeField, Range(0f, 0.1f)] float fluxBundle = 0.016f;

        [Tooltip("Whole turns the bundle twists about its axis over the arc (a braided cable). Whole turns, so each strand still lands on its own sink corner.")]
        [SerializeField, Range(0, 4)] int fluxTurns = 1;

        [Tooltip("A Mass column lights where an arc passes through it only while it stands out of the omni: its strike starts at this protraction (1 - its column place; 0 sealed, 1 at the top of its column)...")]
        [SerializeField, Range(0f, 1f)] float strikeProtractionFrom = 0.15f;

        [Tooltip("...and is full from this protraction up.")]
        [SerializeField, Range(0f, 1f)] float strikeProtractionFull = 0.45f;

        [Header("Bolts")]
        [Tooltip("A bolt's core width, x the crystal's radius (its glow is wider; the flux beam is 3 of these, a strand 0.9).")]
        [SerializeField, Range(0.001f, 0.05f)] float coreWidth = 0.012f;

        [Tooltip("How fast the plasma writhes: the smooth noise that bends each bolt scrolls this many noise cells a second along it (the Squirrel's skim crackle is the reference: one smooth curve, never re-rolled).")]
        [SerializeField, Range(0f, 20f)] float writheSpeed = 3f;

        [Tooltip("How fast a bolt's brightness breathes (smooth noise, +-20%).")]
        [SerializeField, Range(0f, 20f)] float flickerSpeed = 4f;

        public ChargeArcSettings Settings => new()
        {
            Rate = rate, Bolts = boltIntensity, Glow = glowIntensity,
            SeamStrike = seamStrikeSeconds, SeamDwellMin = seamDwellMinSeconds, SeamDwellMax = Mathf.Max(seamDwellMinSeconds, seamDwellMaxSeconds),
            SeamFade = seamFadeSeconds,
            FluxGap = fluxGapSeconds, FluxCharge = fluxChargeSeconds, FluxStrike = fluxStrikeSeconds, FluxHold = fluxHoldSeconds,
            FluxFade = fluxFadeSeconds, FluxFork = fluxFork, FluxMinDegrees = fluxMinDegrees, FluxMaxDegrees = Mathf.Max(fluxMinDegrees, fluxMaxDegrees),
            FluxBundle = fluxBundle, FluxTurns = fluxTurns,
            CoreWidth = coreWidth, WritheSpeed = writheSpeed, FlickerSpeed = flickerSpeed,
            SeamPetalGlow = seamPetalGlow,
            StrikeProtractionFrom = strikeProtractionFrom, StrikeProtractionFull = Mathf.Max(strikeProtractionFrom, strikeProtractionFull),
        };
    }
}
